CREATE TABLE public.export_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_at timestamptz NOT NULL DEFAULT now(), trigger text NOT NULL, status text NOT NULL DEFAULT 'running', files jsonb NOT NULL DEFAULT '[]', row_counts jsonb NOT NULL DEFAULT '{}', error text, created_by uuid, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.export_log TO authenticated;
GRANT ALL ON public.export_log TO service_role;
ALTER TABLE public.export_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY export_log_directors_read ON public.export_log FOR SELECT TO authenticated USING (public.is_tier1_or_super(auth.uid()));
CREATE UNIQUE INDEX export_single_running ON public.export_log ((status)) WHERE status='running';
CREATE TABLE public.export_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), label text NOT NULL, token_hash text NOT NULL UNIQUE, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz, revoked_at timestamptz, updated_by uuid, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.export_tokens TO service_role;
ALTER TABLE public.export_tokens ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.export_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token_id uuid, action text NOT NULL, performed_by uuid NOT NULL, performed_at timestamptz NOT NULL DEFAULT now(), old_value jsonb, new_value jsonb);
GRANT SELECT ON public.export_audit TO authenticated;
GRANT ALL ON public.export_audit TO service_role;
ALTER TABLE public.export_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY export_audit_directors_read ON public.export_audit FOR SELECT TO authenticated USING (public.is_tier1_or_super(auth.uid()));
CREATE FUNCTION public.export_token_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO public.export_audit(token_id,action,performed_by,new_value) VALUES(NEW.id,'created',NEW.created_by,jsonb_build_object('label',NEW.label)); ELSIF OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL THEN INSERT INTO public.export_audit(token_id,action,performed_by,old_value,new_value) VALUES(NEW.id,'revoked',NEW.updated_by,jsonb_build_object('revoked',false),jsonb_build_object('revoked',true)); END IF; RETURN NEW; END $$;
CREATE TRIGGER export_token_audit AFTER INSERT OR UPDATE ON public.export_tokens FOR EACH ROW EXECUTE FUNCTION public.export_token_audit();
CREATE FUNCTION public.export_storage_sizes() RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('database_bytes',pg_database_size(current_database()),'buckets',(SELECT jsonb_agg(x) FROM (SELECT b.id,count(o.id) AS files,coalesce(sum((o.metadata->>'size')::numeric),0) AS bytes FROM storage.buckets b LEFT JOIN storage.objects o ON o.bucket_id=b.id GROUP BY b.id ORDER BY b.id) x)) $$;
REVOKE ALL ON FUNCTION public.export_storage_sizes() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.export_storage_sizes() TO service_role;
CREATE FUNCTION public.export_hourly_rates() RETURNS TABLE(worker_id uuid,worker_code text,name text,contractor text,skill_type text,status text,hourly_rate numeric,effective_hourly_rate numeric) LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT w.id,w.worker_code,w.name,c.company_name,w.skill_type,w.status,comp.hourly_rate,coalesce(comp.hourly_rate,comp.monthly_salary/208::numeric) FROM public.labour_workers w LEFT JOIN public.labour_contractors c ON c.id=w.contractor_id LEFT JOIN public.labour_worker_compensation comp ON comp.worker_id=w.id ORDER BY w.id $$;
REVOKE ALL ON FUNCTION public.export_hourly_rates() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.export_hourly_rates() TO service_role;